import{_ as t,C as r,o as l,c as i,j as e,a as o,E as n,a5 as h}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"社会资本：新富阶层的货币","description":"","frontmatter":{"title":"社会资本：新富阶层的货币","originalTitle":"Social Capital: The Currency Of The New Rich","date":"2024-11-30","originalUrl":"https://thedankoe.com/letters/social-capital-the-currency-of-the-new-rich/","minutes":12,"sourceHash":"a06afb0264eed83cf9c756c41cf7c0b71d06a90940d689b1f77024d899ac493e","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/social-capital-the-currency-of-the-new-rich/"}]]},"headers":[],"relativePath":"letters/social-capital-the-currency-of-the-new-rich.md","filePath":"letters/social-capital-the-currency-of-the-new-rich.md"}'),s={name:"letters/social-capital-the-currency-of-the-new-rich.md"};function c(d,p,m,u,f,b){const a=r("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=e("h1",{id:"社会资本-新富阶层的货币",tabindex:"-1"},[o("社会资本：新富阶层的货币 "),e("a",{class:"header-anchor",href:"#社会资本-新富阶层的货币","aria-label":'Permalink to "社会资本：新富阶层的货币"'},"​")],-1)),n(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/DAgVDVHsApE?si=RZEhKOZEujKGL45Y" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我一直以为建立一家企业是遥不可及的事。</p><p>小时候，你并不懂得更多。</p><p>你唯一相信可能实现的事，就是你父母曾经实现过的事，因为那是你唯一能接触到的信息。随着时间推移，你会形成一些微小却强大的限制性信念，解释为什么你<em>不能</em>拥有更多的自由、更多的钱、更多的满足感。</p><p>这就是我写这封信的原因。</p><p>因为每个人都有过那种想法，你知道的，那种你跟所有朋友都说过，但从来没真正动手去做的想法。</p><p>“兄弟，我们应该做一个像Tinder但用于选饭馆的App。这样人们就不用为吃什么发愁了。”</p><p>但你没能做出那个App，也没能建起那家公司，或者任何你曾梦想过要建的东西。</p><p>为什么？</p><p>你没有钱。</p><p>你以为你需要投资人。</p><p>你缺乏太多知识和技能。</p><p>你喜欢最初的点子，但随后你的脑子里就被LLC、S-corp、隐私政策，以及一堆你根本不想处理的商业狗屁事塞满了。</p><p>我曾经也是这么想的。</p><p>我为此挣扎了相当长一段时间。</p><p>直到我意识到，我需要的不是创业资本，而是<em>社会资本</em>。</p><p>什么是社会资本？</p><p>我们很快会谈到这个问题，但简单来说，<em>它是指在愿意为你提供的价值付费的</em><em><strong>受众</strong></em><em>群体中，拥有良好的声誉。</em></p><p>一旦你拥有了这一点，你就拥有了杠杆：</p><ul><li>你可以在没有唱片公司的情况下成为成功的音乐人。</li><li>你可以在没有出版商的情况下成为成功的作家。</li><li>你可以在没有雇主的情况下成为成功的设计师、程序员，或博学者。</li><li>你几乎可以开始任何一种生意，并拥有让它成功所需的技能和潜在客户。</li><li>你不必依赖外部资金、投资之类的东西。你能快速组建团队或网络。</li></ul><p>更进一步，看看那些仅凭把自己的脸放到品牌上，就能在大公司获得股权的创作者。想想Marques Brownlee是如何成为Ridge Wallet背后的创意合伙人的。或者初创公司如何把股权给创作者，让他们借助受众快速增长，根本不需要付费广告。</p><p>换句话说，社会资本是下一代人的货币，而不是风险投资。</p><p>换个说法，注意力是新的货币，但单纯的注意力可能导致肤浅而虚荣的生活。</p><p>而社会资本，另一方面，兼顾了目的、利润与内心的平静——因为你知道自己正在为这个世界提供价值。</p><h2 id="社会资本-像《黑镜》-但是正面版" tabindex="-1">社会资本：像《黑镜》，但是正面版 <a class="header-anchor" href="#社会资本-像《黑镜》-但是正面版" aria-label="Permalink to &quot;社会资本：像《黑镜》，但是正面版&quot;">​</a></h2><p>你看过Netflix上《黑镜》的那一集吗？</p><p>那一集叫做《急转直下》（Nosedive）？</p><p>没看过？</p><p>它讲的是一个使用社会信用系统的社会。</p><p>你的声誉和价值取决于你作为个人所持有的5星评分。</p><p>每次你和另一个人互动，对方都有机会根据他们与你相处的经历，给你打1到5星。你只需在手机上选择一个评分，向上一划，那个人的评分就会上升或下降。</p><p>你的评分决定你能住在什么样的社区，能从事什么样的工作，什么样的人会接纳你进入他们的社交圈，等等。它非常以貌取人。可以看出，评分接近满4星的是那种富有且高傲的人。评分低的（大多数情况下）是贫穷且暴力的那类人。</p><p>现在，问你一个问题：</p><p>这让你想起了什么吗？</p><p>也许是创作者经济？</p><p>你有没有注意到，越来越多人炫耀自己有很多粉丝？或者那个因为父母粉丝太少而与他们断绝关系的女孩？</p><p>要我说，这有点疯狂。</p><p>但这件事也有正面的一面。</p><h3 id="互联网上的3种人" tabindex="-1">互联网上的3种人 <a class="header-anchor" href="#互联网上的3种人" aria-label="Permalink to &quot;互联网上的3种人&quot;">​</a></h3><p>对于普通人来说，互联网看起来就像《黑镜》里的世界。</p><p>人们赞美那些根本不在乎他们的网红和名人。</p><p>网红和名人获得特殊待遇。品牌合作。想要什么都能得到。他们拥有全部的注意力……他们成为其他品牌借以发声的营销渠道。</p><p>但网红并不是互联网上唯一的人群。</p><p>他们也不是唯一拥有<em>权力</em>的人。</p><p>互联网上<strong>第二种</strong>人是消费者。</p><p>他们不是在那里为网络空间贡献什么。他们不是在那里提供产品或服务。他们只是在那里被教育、被娱乐、被激励，很多时候……被激怒。往往是被网红、名人和政客所激怒。</p><p>但还有第三种人：</p><p><strong>创作者。</strong></p><p>我知道创作者和网红在某种程度上是一样的，但在这里我想对二者做一个区分。</p><p>为了便于解释，创作者是一个<em>价值创造者</em>。</p><p>是那种不会消费到精神肥胖的人，也是那种不会把全部注意力放在虚荣、认可，或点赞数上升上的人。</p><p>价值创造者是这样一种人：他们的价值建立在自己创造出的价值之上。他们写的文字。他们造的产品。他们解决的问题。他们制作的音乐。他们敲下的代码。在社会资本的语境下，创作者的故事还有更多内容。</p><p>他们看重的是影响力而不是点赞，深度而不是外表，真实而不是从众。</p><p>为了创造价值，需要有一群受众——无论大小——认为他们的创作是有价值的。</p><p>如果一棵树在森林里倒下，周围没有人，它会发出声音吗？</p><p>如果一个人做出了一个产品，周围没有人，它会赚到钱吗？它会影响他的生活吗？</p><p>不会。</p><p>1 X 0 = 0</p><p>那么，创作者拥有什么，是网红、名人、政客和消费者所没有的？</p><h3 id="道德社会资本的3大支柱" tabindex="-1">道德社会资本的3大支柱 <a class="header-anchor" href="#道德社会资本的3大支柱" aria-label="Permalink to &quot;道德社会资本的3大支柱&quot;">​</a></h3><p>社会资本不仅仅是关于建立受众。</p><p>任何人都能制作出病毒式传播的TikTok视频和毫无意义的段子来迎合大众，除了偶尔的一笑和尴尬之外，对人类没有任何贡献。</p><p>如果你是一名作家、设计师、程序员，任何一种创意工作者，或者只是一个想靠做自己想做的事来谋生的人，社会资本正是你必须建立的东西。</p><p>社会资本 = 分发 + 声誉 + 价值。</p><p>以下是如何正确地做到这一点：</p><h3 id="分发" tabindex="-1">分发 <a class="header-anchor" href="#分发" aria-label="Permalink to &quot;分发&quot;">​</a></h3><p>有3种类型的分发：</p><ul><li>自建型——比如建立自己的粉丝群或邮件订阅列表。</li><li>借力型——比如别人引用你的书或分享你的帖子。</li><li>购买型——比如付费广告或邮件订阅赞助。</li></ul><p>大多数人无法把一份工作变成一个收入来源的原因是，他们做了各种事，唯独没有去尝试获取客户。</p><p>他们做了App，却搞不到用户。</p><p>他们写了书，却搞不到读者。</p><p>他们做了音乐，却搞不到听众。</p><p>但如果你只是专注于<em>分发</em>，你就能把你的创作展示给其他人。而这也是唯一能让你判断出它到底好不好、有没有用的方式。</p><p>如果没人喜欢你做的东西，你并没有你自以为的那么厉害。</p><p>不，这不是关于寻求认可。这是关于你需要一份收入，好让你的热爱能全职维持下去。否则，生活就会被别人安排。你会为自己找理由，说自己必须去打工，因为没人喜欢你的作品——这样你就不必放下自己的自尊，去真正地帮助别人。</p><p>话虽如此，每个人都应该去<em>自建</em>分发渠道。</p><p>社交媒体是免费的。写作是免费的。两者对任何有网络连接的人都是可及的。</p><p>一旦你建立了分发渠道，并借助它赚到了收入，那时再考虑<em>购买型</em>分发。</p><p>如果你想学习如何通过写作建立分发渠道，可以看看<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">The Writer&#39;s Bootcamp课程。</a></p><h3 id="声誉" tabindex="-1">声誉 <a class="header-anchor" href="#声誉" aria-label="Permalink to &quot;声誉&quot;">​</a></h3><p>你可以靠外表和点赞建立一大批受众，但那不会让你走得很远。</p><p>你建立起的受众，是一群活在生存模式中的人。他们在追逐下一次廉价的多巴胺刺激。他们看到的是你，而不是你的思想。他们把你视为一种商品，一旦有更能带来快感的东西出现在他们屏幕上，你就会被扫进尘埃。</p><p>价值创造者关注的是深度、创造力、解决复杂问题，以及通过传播有助于理解——而不是混乱和不堪重负的洞见——所带来的长期满足感。</p><p>他们靠自己的心智赚钱。</p><p>而不是靠自己的时间、外表或体力劳动。</p><p>一种是无限的。其他的会随时间消逝。</p><p>一种促进负熵（centropy）。<a href="/letters/the-dopamine-epidemic-how-society-failed-to-think-long-term">另一些增加熵（entropy）。</a></p><p>一种对人类是净正的。另一些正在把人类拖入地狱。</p><p>你可以在没有声誉的情况下建立分发渠道，但那样你处境会更糟。</p><p>与没有用户、读者或买家相比，你拥有的是一大批只在乎你身上某个必然会改变的部分的受众。他们不在乎你的作品，未来几年他们也不会在乎你这个人。</p><h3 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to &quot;价值&quot;">​</a></h3><p>你可以整天写作、设计、构建、创造，但这并不意味着它有价值，也不意味着它值得付费。而如果它不值得付费，那祝你好运——在独立维持你的热爱的同时，还想对自己一天的时间拥有哪怕一点掌控权。</p><p>价值 = （人们在意你所做之事的程度） X （你解决的问题的量级）</p><p>价值创造者不是为了创造而创造。</p><p>他们创造，是为了解决真实、切实存在的问题。</p><p>他们不会用那些听起来很酷的创业点子去解决根本不存在的虚构问题。他们解决的是人的问题。健康、财富、人际关系和幸福感。他们为个人移除了通往进步与进化的障碍。</p><p>你可以拥有分发渠道和声誉，但如果你没有解决一个有价值的问题，你就只是一个商品，很快，你就会开始质疑你工作中所带来的那份满足感。你会为了追逐快钱而放弃自己毕生的事业，最终又像所有精疲力竭的商人那样，绕回原地，疑惑自己的人生究竟落到了哪里。</p><h2 id="如何从零开始建立社会资本" tabindex="-1">如何从零开始建立社会资本 <a class="header-anchor" href="#如何从零开始建立社会资本" aria-label="Permalink to &quot;如何从零开始建立社会资本&quot;">​</a></h2><p>让我们先把一件事说清楚。</p><p>大多数人并没有大量的钱可以拿来作为人生或事业的捷径。</p><p>他们看不到通往自己想要的生活的路径，因为他们以为自己得去打工、存钱、时不时投一点小钱，如此等等。</p><p>但接着，他们的梦想就和别人的一样，被葬进了坟墓。他们被责任和消费主义文化裹得越来越紧。</p><p>他们从未建立起自己的事业。他们从未真正掌控过自己的早晨、下午和夜晚。他们陷入一个无休止的循环：带着压力醒来，和自己毫不在乎的人一起工作，回到家累得什么有意义的事都干不了。</p><p>根本性的误解在于：这个世界已经变了。</p><p>我们已经不再处于工业时代，那个唯一的出路就是上学、找一份工作、去实现美国梦的时代。</p><p>金钱并不是唯一的杠杆形式。</p><p>而社会资本，另一方面，可以被用作杠杆，帮你赚到你想要的任何数量的钱。</p><p><em>你通过建立受众来建立社会资本。</em></p><p>以下是具体做法（以及它为何重要）：</p><h3 id="_1-学习一套具有相关性且经得起未来考验的技能组合" tabindex="-1">1）学习一套具有相关性且经得起未来考验的技能组合 <a class="header-anchor" href="#_1-学习一套具有相关性且经得起未来考验的技能组合" aria-label="Permalink to &quot;1）学习一套具有相关性且经得起未来考验的技能组合&quot;">​</a></h3><p>当你打造受众群体时，你会被迫学习一整套几乎对任何人都有用的通用技能：</p><ul><li>写作</li><li>说服力</li><li>产品开发</li><li>营销与销售</li><li>平面设计</li><li>品牌塑造</li><li>流量与转化</li><li>以及更多</li></ul><p>你不会浪费时间去钻研某一项你以为能让自己变得有价值的技能。你打造受众群体，然后让市场告诉你<em>它是否真的有价值。</em></p><p>你不是在孤立的环境中学习这些技能，而是在真实世界中学习它们。你会跳过那些华而不实的东西，只实践能带来结果的部分。而如果你没有得到结果，那很可能是因为你专注在了错误的事情上——认识到这一点本身，就是一段个人和职业发展的旅程。</p><p>而且，你不需要任何人的许可才能开始。</p><p>你只需在网上开始打造自己的个人品牌。你创建横幅、简介、邮件列表，你撰写帖子和长文，你打造并出售一个产品或服务。</p><p>你所做的每一件事，都能让个人和企业从中受益。</p><p>一旦你为自己取得了成果，你就可以将你的技能提供给他人或企业，以此赚取收入。</p><p>最棒的部分是：到那时，你已经拥有了一群<em>愿意</em>为此付钱给你的受众。</p><p>第二棒的部分是：你可以围绕任何你喜欢的其他技能或兴趣来打造受众群体。它不必是关于商业或营销的。它可以是关于哲学、生产力、健身、编程，或任何你早已在网上看到、关注并消费的内容。</p><p>在「一人企业发射台」（One Person Business Launchpad）中，我给你提供了10个帖子模板、3个长文模板、1个通讯模板，并帮助你快速打造一个微型产品和微型服务来起步。<a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">点击这里查看。</a></p><h3 id="_2-从小处、易上手且免费-或极其便宜-的地方开始" tabindex="-1">2）从小处、易上手且免费（或极其便宜）的地方开始 <a class="header-anchor" href="#_2-从小处、易上手且免费-或极其便宜-的地方开始" aria-label="Permalink to &quot;2）从小处、易上手且免费（或极其便宜）的地方开始&quot;">​</a></h3><p>我刚才说的这些可能会让人感到不堪重负。</p><p>你可能会觉得，你<em>必须</em>学会所有这些技能才能积累社会资本。</p><p>如果你聪明地去做，事情并非如此。</p><p>以下是我会采取的做法：</p><ul><li><strong>从写作开始</strong>——你不需要学习视频、音频或平面设计就能在社交媒体上写作。而且，写作能增强你在网上看到的任何视频脚本、音频脚本，或设计中文字部分的影响力。</li><li><strong>从一个短内容平台开始</strong>——X（推特）、LinkedIn（领英）或Threads。你需要一种在某个平台上产生流量的方式，让人们能够<em>发现</em>并关注你。像博客和播客这类东西，可发现性很差。</li><li><strong>从一个长内容平台开始</strong>——我推荐邮件通讯。这样，你就能<em>保留</em>你所积累的一部分关注者。然后，你随时都可以把这些通讯改编成YouTube视频脚本或播客脚本……如果你哪天真想那么做的话。Justin Welsh（贾斯汀·韦尔什）就做得很好，光靠LinkedIn和他的邮件通讯，年入就超过200万美元。</li></ul><p>我为什么推荐这三个步骤？</p><p>因为它们能起到一种强制作用，让你（1）迅速获得结果，并（2）学到真正重要的技能。</p><p>如果你想让你的写作引人入胜、具有影响力，它就必须具有说服力。如果你想建立你的邮件列表，你就需要对营销和销售有基本的理解。</p><p>关键在于，你不需要正式地去学习这些技能。你只需要去尝试、失败、改进。如果你放弃了，那是因为你没有把它看作唯一可行的选择。你宁愿把那些时间用来让自己从「放弃后所接受的那种舒适生活」中分散注意力。</p><p>如果你需要一个新的地方来写作和捕捉想法，<a href="https://app.kortex.co/" target="_blank" rel="noreferrer">试试Kortex</a>（点击「创建账户」，在桌面端登录）。</p><h3 id="_3-建立声誉-分发价值" tabindex="-1">3）建立声誉，分发价值 <a class="header-anchor" href="#_3-建立声誉-分发价值" aria-label="Permalink to &quot;3）建立声誉，分发价值&quot;">​</a></h3><p>大多数人「等着开始卖东西」，是因为他们以为自己的受众不想被推销。</p><p>我为自己的个人和事业发展所做的最棒的事，就是<em>从一开始就</em>销售一个产品。</p><p>那样一来，我的行动就有了动机。我的目标是靠一个能帮助他人的产品来赚取收入。</p><p>我有了<em>方向。</em></p><p>我知道，如果我没有赚到收入，那我其实并没有真正的价值。而如果我的收入没有增长，我的声誉也就没有增长。</p><p>免费的内容、文字、设计，以及其他一切，都不足以真正影响别人的生活。</p><p>他们需要主动地与你进行价值交换。他们需要投资购买你的一个能解决他们生活中问题的产品。因为如果你没有解决他们生活中的问题，那你对他们来说就是可替代的，他们不会记住你，也不会把他们的成果归功于你。</p><p>从我开始以来，过去5年里，我每个季度都打造并推出一个产品或服务。这些产品从电子书、课程、咨询，到一本书、那本书的限量版、训练营、计划本，直到现在的一款叫Kortex的软件。</p><p>这一点在你亲身经历之前很难理解，但我把我所有的社交增长和外界认可的成功，都归因于这一点。</p><p>当我开始的时候，我从没想过自己能走到今天这一步。但我可以毫不夸张地告诉你，这一切之所以可能，仅仅是因为我把我认为有影响力的产品或服务拿去换钱。</p><p>这就是你建立声誉的方式。</p><p>这就是你「传递价值」的方式。</p><p>这就是你摆脱社会矩阵、为互联网这个准自由市场做出贡献的方式。</p><p>如果你因为自己那套局限的思维——自认为更高尚、更具灵性——而害怕金钱或将其妖魔化，那我帮不了你，因为你看不到金钱其实有多种视角，而其中许多视角是极其正向的。</p><p>就是这样。</p><p>积累社会资本。</p><p>加入新富阶层。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/social-capital-the-currency-of-the-new-rich">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',153))])}const g=t(s,[["render",c]]);export{k as __pageData,g as default};
